import re
import asyncio

async def act(page):
    # 1) Attempt to dismiss any obvious popup that might block interactions.
    try:
        close_btns = page.get_by_role("button", name=re.compile(r"^(close|dismiss|×|x)$", re.IGNORECASE))
        if await close_btns.count() > 0:
            try:
                await close_btns.nth(0).click()
            except Exception:
                await close_btns.nth(0).click(force=True)
        else:
            # broader fallback: any button with an X in its name
            x_btns = page.get_by_role("button", name=re.compile(r"×|x", re.IGNORECASE))
            if await x_btns.count() > 0:
                try:
                    await x_btns.nth(0).click()
                except Exception:
                    await x_btns.nth(0).click(force=True)
    except Exception:
        # non-fatal; continue
        pass

    # small pause to allow overlay disappearance animation
    await asyncio.sleep(0.25)

    # 2) Locate the complementary region which contains the search input
    complementary = page.get_by_role("complementary")
    if await complementary.count() == 0:
        raise Exception("No complementary region found on the page containing the search widget")
    complementary = complementary.nth(0)

    # 3) Find the search input: prefer role=searchbox named "Search", fall back to role=textbox
    search_input = complementary.get_by_role("searchbox", name="Search")
    if await search_input.count() == 0:
        search_input = complementary.get_by_role("textbox")
        if await search_input.count() == 0:
            raise Exception("No search input (searchbox or textbox) found in the complementary region")
    search_input = search_input.nth(0)

    # 4) Fill the search term 'Tracing'
    await search_input.fill("Tracing")

    # 5) Activate the search: prefer the Search button inside complementary, else press Enter
    try:
        search_button = complementary.get_by_role("button", name="Search")
        if await search_button.count() > 0:
            try:
                await search_button.nth(0).click()
            except Exception:
                await search_button.nth(0).click(force=True)
        else:
            await search_input.press("Enter")
    except Exception:
        await search_input.press("Enter")

    # 6) Wait for the results to appear in the main region; fallback to networkidle
    try:
        await page.get_by_role("main").wait_for(state="visible", timeout=5000)
    except Exception:
        await page.wait_for_load_state("networkidle")

    # 7) Collect article results inside main and ensure at least two results
    main_region = page.get_by_role("main")
    if await main_region.count() == 0:
        raise Exception("No main region found to read search results from")
    main_region = main_region.nth(0)

    articles = main_region.get_by_role("article")
    count = await articles.count()
    if count < 2:
        raise Exception(f"Expected at least 2 search results, found {count}")

    # 8) Click the second article's heading link using full parent->child selectors. Make this the last action.
    second_article = articles.nth(1)

    heading_locator = second_article.get_by_role("heading")
    if await heading_locator.count() > 0:
        link_in_heading = heading_locator.nth(0).get_by_role("link")
        if await link_in_heading.count() > 0:
            try:
                await link_in_heading.nth(0).click()
            except Exception:
                await link_in_heading.nth(0).click(force=True)
            return

    # fallback: click the first link inside the article
    first_link = second_article.get_by_role("link")
    if await first_link.count() > 0:
        try:
            await first_link.nth(0).click()
        except Exception:
            await first_link.nth(0).click(force=True)
        return

    raise Exception("Could not find a link to click inside the second search-result article")

